boolean zawieraDziewiec(int[] tab, int szukana) {
    for (int liczba : tab) {
        if (liczba == szukana) return true;
    }
    return false; // szukana wartosc jest ostatnia albo jej nie ma - petla przechodzi caly zakres
}

boolean maParaSumujacaSie(int[] liczby, int cel) {
    for (int i = 0; i < liczby.length; i++) {
        for (int j = i + 1; j < liczby.length; j++) {
            if (liczby[i] + liczby[j] == cel) {
                return true;
            }
        }
    }
    return false;
}
