Jaka jest złożoność czasowa poniższej metody (tablica wejściowa jest już posortowana)?
```java
boolean zawiera(int[] posortowana, int cel) {
    int lo = 0, hi = posortowana.length - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (posortowana[mid] == cel) return true;
        if (posortowana[mid] < cel) lo = mid + 1; else hi = mid - 1;
    }
    return false;
}

